        windowDays,
        "windowDays",
      );
      const requestedIds = requireUuidIds(
        normalizedBuildingIds,
        "buildingIds",
      );
      const requestedBuildingIds = new Set(requestedIds);
      const { data, error } = await supabase.rpc(
        "business_performance_upcoming_vacancy_v1",
