      // RPC này CÓ trong types.ts (Args: never, Returns: Json) nên gọi typed
      // được; đọc field qua jsonProp() vì Json không có index signature.
      const { data, error } = await supabase.rpc(
        'get_acceptance_geofence_config',
      );
      if (error) throw error;
      if (!data) throw new TypeError('Missing acceptance geofence configuration');
      const row = Array.isArray(data) ? data[0] : data;
      const enabled = jsonProp(row, 'enabled');
      const radiusM = jsonProp(row, 'radius_m');
      if (typeof enabled !== 'boolean' || typeof radiusM !== 'number' || !Number.isFinite(radiusM)) {
        throw new TypeError('Invalid acceptance geofence configuration');
      }
      return { enabled, radiusM };
    },
    staleTime: 5 * 60 * 1000,
  })

