useQuery({
    queryKey: [
      "income-expenses",
      "accrual-month",
      month,
      filters.building_id,
      filters.building_ids,
      filters.room_id,
      filters.room_ids,
      filters.type,
      filters.approval_status,
      businessResultOnly,
    ],
    queryFn: async (): Promise<AccrualReportResult> => {
      if (!month) return EMPTY;
      const firstOfMonth = monthToStartDate(month); // 'YYYY-MM-01'
      const lastOfMonth = monthToEndDate(month); // ngày cuối tháng

      // Phiếu KHÔNG gắn hoá đơn: lọc theo KỲ của item — kỳ giao tháng YM HOẶC
      // item null-period (nhận lại theo voucher_date ở bước transform).
      const periodOr =
        `and(start_date.lte.${lastOfMonth},end_date.gte.${firstOfMonth}),` +
        `and(start_date.is.null,end_date.is.null)`;

      // Bộ lọc chung (toà/phòng/loại/duyệt/KQKD) áp cho cả 2 truy vấn.
      const applyFilters = (q: any) => {
        if (filters.building_ids?.length) {
          // building_ids: mảng toà từ BuildingMultiSelect — không round-trip.
          q = q.in("building_id", filters.building_ids);
        }
        if (filters.building_id) q = q.eq("building_id", filters.building_id);
        if (filters.room_ids?.length) {
          q = q.in("room_id", filters.room_ids);
        } else if (filters.room_id) {
          q = q.eq("room_id", filters.room_id);
        }
        if (filters.type) q = q.eq("type", filters.type);
        if (filters.approval_status === "ALL_ACTIVE") {
          q = q.in("approval_status", ["APPROVED", "UNAPPROVED"]);
        } else if (filters.approval_status) {
          q = q.eq("approval_status", filters.approval_status);
        }
        // KQKD item-level: chỉ loại phiếu ÉP không-KQKD (override=false); phiếu
        // trộn (thu HĐ gộp cọc) vẫn vào — item cọc bị bỏ ở bước transform.
        if (businessResultOnly) q = q.not("business_result_accounting", "is", false);
        return q;
      };

      // Query builder là thenable DÙNG-MỘT-LẦN → dựng mới mỗi trang.
      // (1) Phiếu KHÔNG gắn hoá đơn: xếp tháng theo KỲ của item (hành vi cũ).
      const buildNonInvoice = (from: number, to: number) => {
        let q = supabase
          .from("income_expenses" as any)
          .select(ACCRUAL_SELECT)
          .is("deleted_at", null)
          .is("invoice_id", null)
          .or(periodOr, { referencedTable: "items" });
        q = applyFilters(q);
        // Tiebreaker `id` để phân trang không sót/trùng ở ranh giới trang.
        return q
          .order("voucher_date", { ascending: false })
          .order("id", { ascending: true })
          .range(from, to);
      };

      // (2) Phiếu GẮN hoá đơn: xếp tháng theo billing_month của HOÁ ĐƠN (kỳ
      // doanh thu) — KHÔNG theo ngày thu tiền. `invoice!inner` đã ràng invoice_id
      // not null; lọc 1 giá trị billing_month.
      const buildInvoice = (from: number, to: number) => {
        let q = supabase
          .from("income_expenses" as any)
          .select(ACCRUAL_SELECT_INV)
          .is("deleted_at", null)
          .eq("invoice.billing_month", month);
        q = applyFilters(q);
        return q
          .order("voucher_date", { ascending: false })
          .order("id", { ascending: true })
          .range(from, to);
      };

      // (3) Phiếu KHÔNG gắn hoá đơn & KHÔNG có item: nhánh (1) (items!inner) đã
      // bỏ chúng. Lọc theo voucher_date trong tháng (cùng cách useIncomeExpenses
      // lọc gte/lte) → ghi nhận total_amount trọn vào tháng. Chỉ phiếu items rỗng
      // mới được dùng (phiếu có item đã thuộc nhánh (1)).
      const buildNonInvoiceNoItem = (from: number, to: number) => {
        let q = supabase
          .from("income_expenses" as any)
          .select(ACCRUAL_SELECT_NOITEM)
          .is("deleted_at", null)
          .is("invoice_id", null)
          .gte("voucher_date", firstOfMonth)
          .lte("voucher_date", lastOfMonth);
        q = applyFilters(q);
        return q
          .order("voucher_date", { ascending: false })
          .order("id", { ascending: true })
          .range(from, to);
      };

      // Tiến theo số dòng thực nhận, kể cả khi server hạ giới hạn dưới 1000.
      const fetchAll = async (
        build: (f: number, t: number) => any,
      ): Promise<any[]> => {
        const out = await fetchAllRows(build, { label: 'accrual-month' });
        if (out === null) throw new Error('Không tải đủ dữ liệu báo cáo. Vui lòng thử lại.');
        return out;
      };

      const candidates = await Promise.all([
        fetchAll(buildNonInvoice),
        fetchAll(buildInvoice),
        fetchAll(buildNonInvoiceNoItem),
      ]);

      // Quan hệ nhúng chỉ chọn ứng viên trong phạm vi hiện tại. Dùng cùng
      // reader với màn phiếu để không hiểu item bị ẩn/cắt thành item không tồn tại.
      const idsByOrg = new Map<string, Set<string>>();
      for (const voucher of candidates.flat()) {
        if (!voucher.organization_id) throw new Error('Không xác định được tổ chức của phiếu.');
        const ids = idsByOrg.get(voucher.organization_id) ?? new Set<string>();
        ids.add(voucher.id);
        idsByOrg.set(voucher.organization_id, ids);
      }
      const snapshots = (await Promise.all([...idsByOrg].map(([org, ids]) =>
        loadIncomeExpenseDetails(org, [...ids]),
      ))).flat();
      const byId = new Map(snapshots.map(row => [row.id, row]));
      const [nonInv, inv, noItem] = candidates.map(group => group.map(voucher => {
        const snapshot = byId.get(voucher.id);
        if (!snapshot) throw new Error('Không tải đủ chi tiết phiếu cho báo cáo.');
        // Các truy vấn ứng viên và RPC là những request riêng: nếu phiếu đổi
        // trạng thái/phạm vi giữa hai lần đọc thì tải lại, không cộng nhầm bộ lọc.
        const scopeFields = ['organization_id', 'building_id', 'room_id', 'type',
          'approval_status', 'business_result_accounting', 'voucher_date', 'invoice_id', 'updated_at'] as const;
        if (scopeFields.some(key => (snapshot[key] ?? null) !== (voucher[key] ?? null))) {
          throw new Error('Phiếu đã thay đổi trong lúc tải báo cáo. Vui lòng thử lại.');
        }
        return {
          ...voucher,
          ...snapshot,
          room: snapshot.room_id === voucher.room?.id ? voucher.room : null,
          building: snapshot.building_name ? { id: snapshot.building_id, name: snapshot.building_name } : null,
          items: snapshot.items.map(item => ({ ...item, income_expense_type: {
            id: item.income_expense_type_id, name: item.type_name,
            category: item.category, is_deposit: item.is_deposit,
          } })),
        };
      }));

      // Transform: phân bổ từng item vào tháng YM (client-side).
      let totalIncome = 0;
      let totalExpense = 0;
      const rows: AccrualReportRow[] = [];

      // Item giả cho phiếu trống hạng mục — khớp nhãn 'Không có hạng mục' của
      // fa_accrual_allocations (a_noitem/b_noitem), category NULL.
      const NOITEM_TYPE: Pick<AccrualItemType, "name" | "category"> = {
        name: "Không có hạng mục",
        category: null,
      };

      const pushRow = (
        voucher: any,
        it: any,
        portion: number,
        startDate: string | null,
        endDate: string | null,
      ) => {
        const isIncome = voucher.type === "INCOME";
        if (isIncome) totalIncome += portion;
        else totalExpense += portion;
        const t = it.income_expense_type;
        // Cờ KQKD theo TỪNG DÒNG (item-level): dòng cọc không tính (trừ phiếu
        // ép TRUE); phiếu ép FALSE thì mọi dòng không tính. Phiếu trộn: dòng
        // doanh thu vẫn counts=true dù cờ cả-phiếu counts_in_business_result=false.
        const rowCounts =
          voucher.business_result_accounting === false
            ? false
            : voucher.business_result_accounting === true
              ? true
              : it.accounting_class != null
                ? it.accounting_class === "PNL"
                : !t?.is_deposit;
        rows.push({
          itemId: it.id,
          voucherId: voucher.id,
          voucherName: voucher.name ?? "",
          buildingName: voucher.building?.name ?? null,
          roomName: voucher.room?.name ?? null,
          roomId: voucher.room_id ?? voucher.room?.id ?? null,
          typeName: t?.name ?? "",
          category: t?.category ?? null,
          typeId: it.income_expense_type_id ?? t?.id ?? null,
          startDate,
          endDate,
          income: isIncome ? portion : 0,
          expense: isIncome ? 0 : portion,
          countsInBusinessResult: rowCounts,
          invoiceId: voucher.invoice_id ?? null,
          approvalStatus: voucher.approval_status === "UNAPPROVED" ? "UNAPPROVED" : "APPROVED",
        });
      };

      // KQKD item-level: KHỚP fa_accrual_allocations — engine lọc theo
      // item.accounting_class='PNL' (trừ phiếu ép TRUE). Lọc bằng is_deposit là
      // SAI LỆCH đã đo được (V2-PRE-1): item CUSTOMER_CREDIT/INTERNAL — vd "Tiền
      // khách trả thừa" trong phiếu thu HĐ — không phải doanh thu nhưng
      // is_deposit=false nên lọt vào tổng (+1,2tr). Fallback: item cũ chưa có
      // accounting_class (null) coi như PNL, và vẫn loại cọc theo is_deposit.
      const skipDepositItem = (voucher: any, it: any) => {
        if (!businessResultOnly) return false;
        if (voucher.business_result_accounting === true) return false;
        const cls = it?.accounting_class ?? null;
        if (cls != null) return cls !== "PNL";
        return !!it?.income_expense_type?.is_deposit;
      };

      // (1) Phiếu KHÔNG gắn hoá đơn: phân bổ theo kỳ của item; null-period →
      // ghi nhận trọn vào tháng của voucher_date.
      for (const voucher of nonInv) {
        const vMonth = (voucher.voucher_date ?? "").slice(0, 7);
        for (const it of (voucher.items ?? []) as any[]) {
          if (skipDepositItem(voucher, it)) continue;
          const amount = Number(it.amount);
          const itemAmount = Number.isFinite(amount)
            ? amount
            : Number(it.quantity) * Number(it.unit_price) || 0;

          let portion = 0;
          if (it.start_date && it.end_date) {
            const alloc = allocateAmountByMonth(itemAmount, it.start_date, it.end_date);
            portion = alloc.find((p) => p.month === month)?.amount ?? 0;
          } else {
            portion = vMonth === month ? itemAmount : 0;
          }
          if (portion === 0) continue;
          pushRow(voucher, it, portion, it.start_date ?? null, it.end_date ?? null);
        }
      }

      // (2) Phiếu GẮN hoá đơn: doanh thu nhận TRỌN vào tháng kỳ hoá đơn
      // (billing_month đã lọc = month), bất kể ngày thu. Kỳ hiển thị = tháng HĐ.
      for (const voucher of inv) {
        const items = (voucher.items ?? []) as any[];
        for (const it of items) {
          if (skipDepositItem(voucher, it)) continue;
          const amount = Number(it.amount);
          const itemAmount = Number.isFinite(amount)
            ? amount
            : Number(it.quantity) * Number(it.unit_price) || 0;
          if (itemAmount === 0) continue;
          pushRow(voucher, it, itemAmount, firstOfMonth, lastOfMonth);
        }
        // Phiếu HĐ trống item → total_amount trọn vào billing_month (a_noitem).
        if (items.length === 0) {
          const amt = Number(voucher.total_amount);
          if (amt)
            pushRow(
              voucher,
              { id: voucher.id, income_expense_type: NOITEM_TYPE },
              amt,
              firstOfMonth,
              lastOfMonth,
            );
        }
      }

      // (3) Phiếu KHÔNG gắn hoá đơn & trống item: total_amount trọn vào tháng
      // voucher_date (b_noitem). Bỏ phiếu có item — đã thuộc nhánh (1).
      for (const voucher of noItem) {
        if (((voucher.items ?? []) as any[]).length > 0) continue;
        const amt = Number(voucher.total_amount);
        if (!amt) continue;
        pushRow(voucher, { id: voucher.id, income_expense_type: NOITEM_TYPE }, amt, null, null);
      }

      // §2.3: tách phần thuộc phiếu Chờ duyệt (đã nằm TRONG tổng) để hiển thị
      // counter riêng + tie-out engine chia cổ đông (engine chỉ tính APPROVED).
      let pendingIncome = 0;
      let pendingExpense = 0;
      const pendingVouchers = new Set<string>();
      for (const r of rows) {
        if (r.approvalStatus !== "UNAPPROVED") continue;
        pendingIncome += r.income;
        pendingExpense += r.expense;
        pendingVouchers.add(r.voucherId);
      }

      return {
        totalIncome,
        totalExpense,
        difference: totalIncome - totalExpense,
        rows,
        pendingIncome,
        pendingExpense,
        pendingCount: pendingVouchers.size,
      };
    },
  })

