useQuery({
    queryKey: ["revenue-chart", months, buildingId],
    meta: { errorDisplay: "inline" },
    queryFn: async (): Promise<RevenueData[]> => {
      const userId = await getSessionUserId();
      if (!userId) throw new Error('Not authenticated');

      const rangeStart = startOfMonth(subMonths(new Date(), months - 1));
      const rangeEnd = endOfMonth(new Date());

      // RPC gộp theo tháng server-side (20260726132000) — bản cũ fetchAllRows
      // toàn bộ bút toán P&L cả kỳ về client chỉ để cộng ra 12 con số.
      // Range vẫn do client tính để giữ đúng múi giờ máy user.
      const { data: monthRows, error } = await supabase.rpc("revenue_by_month", {
        p_start: format(rangeStart, "yyyy-MM-dd"),
        p_end: format(rangeEnd, "yyyy-MM-dd"),
        p_building_id: buildingId ?? undefined,
      });
      if (error) throw error;

      // Khởi tạo đủ 12 tháng (tháng không có bút toán P&L vẫn hiện 0).
      const byMonth = new Map<string, number>();
      const data: RevenueData[] = [];
      for (let i = months - 1; i >= 0; i--) {
        const key = format(subMonths(new Date(), i), "MM/yyyy");
        byMonth.set(key, 0);
        data.push({ month: key, revenue: 0 });
      }
      for (const row of monthRows ?? []) {
        const d = new Date(`${row.month_start}T00:00:00`);
        if (Number.isNaN(d.getTime())) continue;
        const key = format(d, "MM/yyyy");
        if (byMonth.has(key)) {
          byMonth.set(key, (byMonth.get(key) || 0) + (Number(row.revenue) || 0));
        }
      }
      for (const row of data) {
        row.revenue = byMonth.get(row.month) || 0;
      }

      // Calculate growth
      for (let i = 1; i < data.length; i++) {
        const current = data[i].revenue;
        const previous = data[i - 1].revenue;
        if (previous > 0) {
          data[i].growth = ((current - previous) / previous) * 100;
        }
      }

      return data;
    },
  })

useQuery({
    ...dashboardSummaryQuery(buildingId),
    select: (s: DashboardSummary): OccupancyData[] => {
      const totalRooms = s.total_rooms || 0;
      const occupiedRooms = s.occupied_rooms || 0;
      const reservedRooms = s.reserved_rooms || 0;
      const availableRooms = Math.max(0, totalRooms - occupiedRooms - reservedRooms);
      const total = totalRooms || 1;

      const result: OccupancyData[] = [
        {
          status: "Đã thuê",
          count: occupiedRooms,
          percentage: (occupiedRooms / total) * 100,
        },
        {
          status: "Còn trống",
          count: availableRooms,
          percentage: (availableRooms / total) * 100,
        },
      ];
      if (reservedRooms > 0) {
        result.push({
          status: "Đã cọc",
          count: reservedRooms,
          percentage: (reservedRooms / total) * 100,
        });
      }
      return result;
    },
  })

useQuery({
    queryKey: ["dashboard-alerts", buildingId],
    meta: { errorDisplay: "inline" },
    queryFn: async (): Promise<Alert[]> => {
      const userId = await getSessionUserId();
      if (!userId) throw new Error('Not authenticated');

      const alerts: Alert[] = [];

      // Overdue invoices
      const { data: overdueInvoices, error: overdueInvoicesError } = await supabase
        .from("invoices")
        .select(
          `id, invoice_number, due_date, total_amount, paid_amount,
           contract:contracts(
             contract_customers!contract_customers_contract_id_fkey(
               is_representative,
               customer:customers!contract_customers_customer_id_fkey(full_name)
             )
           )`
        )
        .in("status", ["APPROVED", "PARTIAL_PAID"])
        .is("deleted_at", null)
        .lt("due_date", new Date().toISOString())
        .order("due_date", { ascending: true })
        .limit(5);

      if (overdueInvoicesError) throw overdueInvoicesError;

      overdueInvoices?.forEach((invoice: any) => {
        const debt = (invoice.total_amount || 0) - (invoice.paid_amount || 0);
        const customerName = getRepresentativeName(invoice.contract, "Khách hàng");
        alerts.push({
          id: invoice.id,
          type: "overdue_invoice",
          title: "Hóa đơn quá hạn",
          description: `${customerName} - ${invoice.invoice_number || "Hóa đơn"} - Nợ ${debt.toLocaleString()}đ`,
          severity: "high",
          date: invoice.due_date,
          link: `/invoices/${invoice.id}`,
        });
      });

      // Expiring contracts (within 30 days)
      const thirtyDaysFromNow = new Date();
      thirtyDaysFromNow.setDate(thirtyDaysFromNow.getDate() + 30);

      const { data: expiringContracts, error: expiringContractsError } = await supabase
        .from("contracts")
        .select(
          `id, contract_number, end_date,
           contract_customers!contract_customers_contract_id_fkey(
             is_representative,
             customer:customers!contract_customers_customer_id_fkey(full_name)
           )`
        )
        .in("status", ["ACTIVE"])
        .lte("end_date", thirtyDaysFromNow.toISOString())
        .gte("end_date", new Date().toISOString())
        .order("end_date", { ascending: true })
        .limit(5);

      if (expiringContractsError) throw expiringContractsError;

      expiringContracts?.forEach((contract: any) => {
        const daysLeft = Math.ceil((new Date(contract.end_date).getTime() - Date.now()) / (1000 * 60 * 60 * 24));
        const customerName = getRepresentativeName(contract, "Khách hàng");
        alerts.push({
          id: contract.id,
          type: "expiring_contract",
          title: "Hợp đồng sắp hết hạn",
          description: `${customerName} - ${contract.contract_number} - Còn ${daysLeft} ngày`,
          severity: daysLeft <= 7 ? "high" : daysLeft <= 15 ? "medium" : "low",
          date: contract.end_date,
          link: `/contracts/${contract.id}`,
        });
      });

      // Unresolved urgent issues > 24h
      const twentyFourHoursAgo = new Date();
      twentyFourHoursAgo.setHours(twentyFourHoursAgo.getHours() - 24);

      const { data: urgentIssues, error: urgentIssuesError } = await supabase
        .from("issues")
        .select("id, title, priority, created_at")
        .eq("priority", "URGENT")
        .not("status", "in", '("RESOLVED","CLOSED")')
        .lt("created_at", twentyFourHoursAgo.toISOString())
        .order("created_at", { ascending: true })
        .limit(5);

      if (urgentIssuesError) throw urgentIssuesError;

      urgentIssues?.forEach((issue) => {
        alerts.push({
          id: issue.id,
          type: "urgent_issue",
          title: "Công việc khẩn cấp chưa xử lý",
          description: `${issue.title} - Quá 24h chưa giải quyết`,
          severity: "high",
          date: issue.created_at,
          link: `/issues/${issue.id}`,
        });
      });

      // Deposit shortfall — HĐ đang hiệu lực còn thiếu cọc (mode DEBT/legacy;
      // KHÔNG gồm FIRST_INVOICE vì khoản đó thu qua hoá đơn đầu, đã có cảnh báo
      // hoá đơn quá hạn riêng). Đánh dấu để admin nhớ thu đủ cọc.
      const { data: depositShortContracts, error: depositShortContractsError } = await supabase
        .from("contracts")
        .select(
          `id, contract_number, total_deposit, deposit_paid, deposit_remaining, deposit_topup_due_date,
           contract_customers!contract_customers_contract_id_fkey(
             is_representative,
             customer:customers!contract_customers_customer_id_fkey(full_name)
           )`
        )
        .in("status", ["ACTIVE"])
        .is("deleted_at", null)
        .gte("deposit_remaining", 10000)
        .or("deposit_debt_mode.is.null,deposit_debt_mode.eq.DEBT")
        .order("deposit_remaining", { ascending: false })
        .limit(5);

      if (depositShortContractsError) throw depositShortContractsError;

      depositShortContracts?.forEach((c: any) => {
        const customerName = getRepresentativeName(c, "Khách hàng");
        const dueIso = c.deposit_topup_due_date as string | null;
        const overdue = dueIso ? new Date(dueIso).getTime() < Date.now() : false;
        const dueText = dueIso
          ? ` - hẹn ${new Date(dueIso).toLocaleDateString("vi-VN")}`
          : "";
        alerts.push({
          id: `deposit-${c.id}`,
          type: "deposit_shortfall",
          title: "Hợp đồng thiếu cọc",
          description: `${customerName} - ${c.contract_number || "HĐ"} - Thiếu ${Number(
            c.deposit_remaining || 0,
          ).toLocaleString()}đ${dueText}`,
          severity: overdue ? "high" : "medium",
          date: dueIso || new Date().toISOString(),
          link: `/contracts/${c.id}`,
        });
      });

      return alerts.sort((a, b) => {
        const severityOrder = { high: 0, medium: 1, low: 2 };
        return severityOrder[a.severity] - severityOrder[b.severity];
      });
    },
  })

useQuery({
    queryKey: ["recent-activities", buildingId],
    meta: { errorDisplay: "inline" },
    queryFn: async (): Promise<RecentActivity[]> => {
      const userId = await getSessionUserId();
      if (!userId) throw new Error('Not authenticated');

      const activities: RecentActivity[] = [];

      // Recent contracts (last 7 days)
      const sevenDaysAgo = new Date();
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

      const { data: recentContracts, error: recentContractsError } = await supabase
        .from("contracts")
        .select(
          `id, contract_number, created_at,
           contract_customers!contract_customers_contract_id_fkey(
             is_representative,
             customer:customers!contract_customers_customer_id_fkey(full_name)
           ),
           room:rooms(name)`
        )
        .gte("created_at", sevenDaysAgo.toISOString())
        .order("created_at", { ascending: false })
        .limit(5);

      if (recentContractsError) throw recentContractsError;

      recentContracts?.forEach((contract: any) => {
        const customerName = getRepresentativeName(contract, "Khách hàng");
        activities.push({
          id: contract.id,
          type: "contract",
          title: "Hợp đồng mới",
          description: `${customerName} - ${contract.room?.name || "Căn hộ"}`,
          date: contract.created_at,
        });
      });

      // Cash collection activities only. The view removes reversals and returned
      // change; customer credit stays included, while non-cash CT is excluded.
      const { data: recentReceipts, error: receiptsError } = await supabase
        .from("active_payment_receipts")
        .select("id, invoice_id, collected_amount, payment_date")
        .neq("payment_method", "CT")
        .gt("collected_amount", 0)
        .gte("payment_date", format(sevenDaysAgo, "yyyy-MM-dd"))
        .order("payment_date", { ascending: false })
        .order("id", { ascending: true })
        .limit(5);
      if (receiptsError) throw receiptsError;

      const invoiceIds = Array.from(new Set(
        (recentReceipts ?? [])
          .map((receipt: any) => receipt.invoice_id as string | null)
          .filter((id: string | null): id is string => !!id),
      ));
      const invoiceById = new Map<string, any>();
      if (invoiceIds.length > 0) {
        const { data: receiptInvoices, error: invoicesError } = await supabase
          .from("invoices")
          .select(
            `id,
             contract:contracts(
               contract_customers!contract_customers_contract_id_fkey(
                 is_representative,
                 customer:customers!contract_customers_customer_id_fkey(full_name)
               )
             )`,
          )
          .in("id", invoiceIds);
        if (invoicesError) throw invoicesError;
        for (const invoice of receiptInvoices ?? []) {
          invoiceById.set(invoice.id, invoice);
        }
      }

      recentReceipts?.forEach((receipt: any) => {
        const invoice = receipt.invoice_id ? invoiceById.get(receipt.invoice_id) : null;
        const customerName = getRepresentativeName(invoice?.contract, "Khách hàng");
        activities.push({
          id: receipt.id,
          type: "payment",
          title: "Thu tiền",
          description: customerName,
          date: receipt.payment_date,
          amount: Number(receipt.collected_amount) || 0,
        });
      });

      // Recent issues (last 7 days)
      const { data: recentIssues, error: recentIssuesError } = await supabase
        .from("issues")
        .select("id, title, priority, created_at")
        .gte("created_at", sevenDaysAgo.toISOString())
        .order("created_at", { ascending: false })
        .limit(5);

      if (recentIssuesError) throw recentIssuesError;

      recentIssues?.forEach((issue) => {
        activities.push({
          id: issue.id,
          type: "issue",
          title: "Công việc mới",
          description: issue.title,
          date: issue.created_at,
        });
      });

      return activities.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 10);
    },
  })

useQuery({
    queryKey: ['can-reverse-collection', ids.join(',')],
    meta:{errorDisplay:'inline',label:'điều kiện hoàn tác khoản thu'},
    enabled: ids.length > 0,
    staleTime: 30_000,
    queryFn: async (): Promise<Record<string, CollectionReversalEligibility>> => {
      const { data, error } = await supabase.rpc('can_reverse_collection_v1', {
        p_collection_ids: ids,
      });
      if (error) throw error;
      const map: Record<string, CollectionReversalEligibility> = {};
      for (const row of financialReadRows(data)) {
        if(typeof row.collection_id!=='string'||!row.collection_id||!['IN_PLACE_CANCEL','COUNTER_VOUCHER','BLOCKED'].includes(row.mode)||(row.reason_code!==null&&!Object.prototype.hasOwnProperty.call(COLLECTION_BLOCK_TEXT,row.reason_code)))throw new TypeError('Chưa đọc được điều kiện hoàn tác khoản thu.');
        map[row.collection_id] = {...row,mode:row.mode as CollectionReversalEligibility['mode'],reason_code:row.reason_code as CollectionReversalBlockCode|null};
      }
      return map;
    },
  })

useMutation({
    mutationFn: async ({
      payment_id,
      collection_id,
      reason: rawReason,
    }: DeletePaymentInput): Promise<DeletePaymentResult> => {
      // Chặn TRƯỚC mọi lời gọi mạng: không có lý do thật thì không hoàn tác.
      const reason = (rawReason ?? '').trim();
      if (reason.length < REVISION_REASON_MIN || reason.length > REVISION_REASON_MAX) {
        throw new Error(UNDO_REASON_REQUIRED_TEXT);
      }
      const paymentId = payment_id?.trim() || null;
      let collectionId = collection_id?.trim() || null;

      // Older callers only know payment_id. Resolve its collection once so a
      // multi-tender V5 receipt still reverses at collection scope.
      if (!collectionId) {
        if (!paymentId) {
          throw new Error('Không tìm thấy nguồn giao dịch cần hoàn tác');
        }
        const { data: payment, error: paymentError } = await supabase
          .from('payments')
          .select('id, collection_id')
          .eq('id', paymentId)
          .single();
        if (paymentError || !payment) {
          throw paymentError ?? new Error('Không tìm thấy giao dịch thu');
        }
        collectionId = (payment as { collection_id?: string | null }).collection_id ?? null;
      }

      return workflow.run(collectionId??paymentId!,'hoàn tác khoản thu',async progress=>{
      const outcome = await reverseInvoicePaymentBySource(
        (fn, args) => supabase.rpc(fn, args as never),
        {
          payment_id: paymentId,
          collection_id: collectionId,
          reversal_date: todayISO(),
          reason,
          idempotency_key: progress.requestKey,
        },
      );

      const receipt=outcome.result as {collection_id?:unknown;payment_id?:unknown;status?:unknown;mode?:unknown}|null;
      if(collectionId ? receipt?.collection_id!==collectionId||receipt.status!=='REVERSED'||!outcome.reversalMode : receipt?.payment_id!==paymentId||receipt.mode!=='DELETED')throw new TypeError('Chưa xác nhận được nguồn và kết quả hoàn tác khoản thu.');
      progress.completed.push({id:collectionId??paymentId!,label:`Đã hoàn tác ${collectionId?'lần thu':'thanh toán cũ'} ${collectionId??paymentId}`});
      return {
        payment_id: paymentId,
        collection_id: collectionId,
        mode: outcome.source === 'COLLECTION'
          ? 'COLLECTION_REVERSED'
          : 'LEGACY_PAYMENT_REVERSED',
        reversalMode: outcome.reversalMode,
      };
      },undefined,selectedOrganizationId??undefined);
    },
    onSuccess: (result) => {
      // Đợt 5: huỷ tại chỗ đổi TRẠNG THÁI phiếu thu gốc và rút tiền khỏi sổ
      // quỹ ngay, nên mọi màn hình đọc sổ quỹ / dòng tiền / phân tích tài chính
      // phải được kéo lại — thiếu là người dùng nhìn hai con số khác nhau cho
      // tới lúc F5.
      for (const key of [
        ['invoice-payments-summary'],
        ['invoices'],
        ['invoice-rounding-report'],
        ['invoice'],
        ['payments'],
        ['invoice-statistics'],
        ['income-expenses'],
        ['income-expense-batches'],
        ['accounts-with-balance'],
        ['excess-amount'],
        ['invoice-collectors'],
        ['handover-vouchers'],
        ['first-invoice-details'],
        ['contract-deposit-vouchers'],
        ['cash-book-summary'],
        ['cash-flow-by-day'],
        ['voucher-with-batch'],
        ['voucher-cancellation'],
        ['ie-history'],
        ['settlement-report'],
        ['financial-analysis'],
        ['can-reverse-collection'],
      ]) {
        queryClient.invalidateQueries({ queryKey: key });
      }

      const description = result.mode !== 'COLLECTION_REVERSED'
        ? 'Khoản thanh toán cũ đã được xử lý hoàn tác. Kiểm tra lịch sử hoá đơn và chứng từ liên quan.'
        : result.reversalMode === 'IN_PLACE_CANCEL'
          ? 'Phiếu thu đã chuyển sang ĐÃ HUỶ và tiền đã trừ khỏi sổ quỹ. Không có phiếu đối ứng nào được sinh thêm.'
          : 'Toàn bộ các dòng TM/TK/TT trong cùng lần thu đã được hoàn tác bằng phiếu chi đối ứng.';

      toast({
        title: result.mode === 'COLLECTION_REVERSED'
          ? 'Đã hoàn tác lần thu tiền'
          : 'Đã hoàn tác phiếu thanh toán cũ',
        description,
      });
    },
    onError: (error: Error) => {
      // Kỳ đã đóng đến từ TRIGGER/vị ngữ dùng chung với tiền tố [CASHBOOK_CLOSED]
      // / [HANDOVER_LOCKED] / [PROFIT_LOCKED]; in thẳng SQLERRM ra toast là ném
      // cả dấu ngoặc vuông vào mặt người dùng.
      toast({
        variant: 'destructive',
        title: 'Không thể hoàn tác khoản thu',
        description: error instanceof FinancialWorkflowError ? workflowErrorMessage(error,'hoàn tác khoản thu') : periodBlockMessage(error?.message) ? undoErrorText(error?.message) : invoiceFailureMessage(error,'hoàn tác khoản thu'),
      });
    },
  })

toast({
        title: result.mode === 'COLLECTION_REVERSED'
          ? 'Đã hoàn tác lần thu tiền'
          : 'Đã hoàn tác phiếu thanh toán cũ',
        description,
      })

toast({
