useQuery({
    meta:{errorDisplay:'inline',label:'thống kê cọc'},
    queryKey: ['deposit-dashboard', 'held'],
    queryFn: async (): Promise<HeldDepositRow[]> => {
      // PAGED: danh sách HĐ ACTIVE có thể > 1000 → phân trang kẻo bảng bị cắt.
      const data = await fetchAllRows<any>(
        (from, to) => supabase
          .from('contracts')
          .select(`
            id, contract_number, total_deposit, deposit_paid, deposit_remaining,
            deposit_debt_mode, deposit_topup_due_date,
            room:rooms!contracts_room_id_fkey (
              id, name,
              building:buildings!rooms_building_id_fkey ( id, name )
            ),
            contract_customers!contract_customers_contract_id_fkey (
              is_representative,
              customer:customers!contract_customers_customer_id_fkey ( full_name )
            )
          `)
          .in('status', ['ACTIVE'])
          .is('deleted_at', null)
          .order('id', { ascending: true })
          .range(from, to),
        { label: 'deposits.held' },
      );
      if (data === null) throw new Error('Lỗi tải danh sách cọc đang giữ');

      return data.map((c: any): HeldDepositRow => {
        const total = nn(c.total_deposit);
        const paid = nn(c.deposit_paid);
        const remaining =
          c.deposit_remaining != null ? nn(c.deposit_remaining) : total - paid;
        const isShort = remaining >= DEPOSIT_SHORTFALL_THRESHOLD;
        const state: HeldDepositState = !isShort
          ? 'FULL'
          : c.deposit_debt_mode === 'FIRST_INVOICE'
            ? 'FIRST_INVOICE'
            : 'SHORT';
        return {
          contract_id: c.id,
          contract_number: c.contract_number ?? null,
          building_id: c.room?.building?.id ?? '',
          building_name: c.room?.building?.name ?? '—',
          room_name: c.room?.name ?? '—',
          customer_name: repName(c.contract_customers),
          total_deposit: total,
          deposit_paid: paid,
          deposit_remaining: remaining,
          deposit_debt_mode: c.deposit_debt_mode ?? null,
          deposit_topup_due_date: c.deposit_topup_due_date ?? null,
          state,
        };
      });
    },
  })

useQuery({
    meta:{errorDisplay:'inline',label:'thống kê cọc'},
    queryKey: ['deposit-dashboard', 'refunds-forfeits'],
    queryFn: async (): Promise<RefundForfeitRow[]> => {
      // PAGED cả hai nhánh: thanh lý và phiếu hoàn đều tích luỹ mãi → phân trang
      // (order + id tiebreaker). CỐ Ý KHÔNG select `refund_date` nữa: nó do cùng
      // câu UPDATE với status='COMPLETED' đặt ra nên không nói được gì về tiền.
      const [data, vouchers] = await Promise.all([
        fetchAllRows<any>(
          (from, to) => supabase
            .from('contract_terminations')
            .select(`
              id, contract_id, termination_date, termination_type,
              total_deposit, total_deductions, refund_amount, status,
              contract:contracts!contract_terminations_contract_id_fkey (
                contract_number,
                room:rooms!contracts_room_id_fkey (
                  name,
                  building:buildings!rooms_building_id_fkey ( id, name )
                ),
                contract_customers!contract_customers_contract_id_fkey (
                  is_representative,
                  customer:customers!contract_customers_customer_id_fkey ( full_name )
                )
              )
            `)
            .order('termination_date', { ascending: false })
            .order('id', { ascending: true })
            .range(from, to),
          { label: 'deposits.refundsForfeits' },
        ),
        fetchAllRows<any>(
          (from, to) => supabase
            .from('income_expenses')
            .select('id, code, contract_id, total_amount')
            .eq('type', 'EXPENSE')
            .eq('system_source', TERMINATION_REFUND_SOURCE)
            .eq('approval_status', 'APPROVED')
            .eq('posting_status', 'POSTED')
            .not('active_posting_id_v2', 'is', null)
            .not('contract_id', 'is', null)
            .is('deleted_at', null)
            .order('id', { ascending: true })
            .range(from, to),
          { label: 'deposits.postedRefundVouchers' },
        ),
      ]);
      if (data === null) throw new Error('Lỗi tải danh sách hoàn/bỏ cọc');
      // FAIL-CLOSED: nếu không đọc được phiếu thì THROW, tuyệt đối không coi là
      // "chưa có phiếu hoàn" — đó lại là một tuyên bố sai về tiền.
      if (vouchers === null) {
        throw new Error('Lỗi tải phiếu hoàn cọc đã vào sổ — chưa thể kết luận đã hoàn hay chưa');
      }

      const posted = indexPostedRefunds(
        vouchers.map((v: any): PostedRefundVoucher => ({
          contract_id: v.contract_id,
          code: v.code ?? null,
          amount: nn(v.total_amount),
        })),
      );

      return data.map((t: any): RefundForfeitRow => {
        const kind: RefundForfeitKind =
          t.termination_type === 'FORFEIT' ? 'FORFEIT' : 'REFUND';
        const agg = posted.get(t.contract_id) ?? { total: 0, count: 0, codes: [] };
        const settlementNet = nn(t.refund_amount);
        return {
          id: t.id,
          contract_id: t.contract_id,
          contract_number: t.contract?.contract_number ?? null,
          building_id: t.contract?.room?.building?.id ?? '',
          building_name: t.contract?.room?.building?.name ?? '—',
          room_name: t.contract?.room?.name ?? '—',
          customer_name: repName(t.contract?.contract_customers),
          termination_date: t.termination_date,
          termination_type: t.termination_type,
          kind,
          total_deposit: nn(t.total_deposit),
          total_deductions: nn(t.total_deductions),
          settlement_net: settlementNet,
          status: t.status,
          posted_refund: agg.total,
          posted_refund_count: agg.count,
          posted_refund_codes: agg.codes,
          refund_done: agg.count > 0,
          refund_drift: settlementNet > 0 ? settlementNet - agg.total : 0,
        };
      });
    },
  })

useQuery({
    queryKey: ['orphan-deposit-vouchers', roomId, startDate],
    enabled: !!roomId,
    queryFn: async (): Promise<OrphanDepositVoucher[]> => {
      if (!roomId) return [];
      let query = supabase
        .from('income_expenses')
        .select(
          `id, code, name, total_amount, voucher_date, approval_status,
           income_expense_items!inner ( id, amount, income_expense_types!inner ( is_deposit ) ),
           settled:reservation_deposit_settlements!reservation_deposit_settlements_source_voucher_id_fkey ( id )`,
        )
        .is('contract_id', null)
        .is('deleted_at', null)
        .eq('type', 'INCOME')
        .eq('room_id', roomId)
        .in('approval_status', ['APPROVED', 'UNAPPROVED'])
        .eq('income_expense_items.income_expense_types.is_deposit', true)
        .is('settled', null);

      if (startDate) {
        const d = new Date(startDate);
        if (!Number.isNaN(d.getTime())) {
          d.setDate(d.getDate() + 7);
          query = query.lte('voucher_date', d.toISOString().split('T')[0]);
        }
      }

      const { data, error } = await query;
      if (error) throw error;
      return financialReadRows(data).map((v: any) => {
        if(!['UNAPPROVED','APPROVED','CANCELLED'].includes(v.approval_status)) throw new TypeError('Chưa đọc được trạng thái phiếu cọc.');
        // Số CỌC = Σ item cọc (embed đã lọc is_deposit) — phiếu thuần cọc thì
        // bằng total_amount; phiếu trộn (hiếm, nhập tay) không đếm thừa phần khác.
        const depositSum = financialReadRows(v.income_expense_items).reduce<number>(
          (s: number, it: any) => s + financialReadNumber(it.amount),
          0,
        );
        return {
          id: v.id,
          code: v.code ?? null,
          name: v.name,
          total_amount: depositSum,
          voucher_date: v.voucher_date,
          approval_status: v.approval_status,
        };
      });
    },
  })

useQuery({
    queryKey: ['reservation-deposits', buildingIds ?? []],
    queryFn: async (): Promise<ReservationDepositRow[]> => {
      // PAGED: phiếu cọc giữ chỗ tích luỹ mãi → phân trang (order voucher_date + id).
      const data = await fetchAllRows<any>(
        (from, to) => {
          let query = supabase
            .from('income_expenses')
            .select(
              `id, code, name, payer_name, total_amount, voucher_date,
               approval_status, approval_version, building_id, room_id,
               building:buildings!income_expenses_building_id_fkey ( id, name ),
               room:rooms!income_expenses_room_id_fkey ( id, name ),
               ${RESERVATION_SETTLED_EMBED},
               ${RESERVATION_MANAGEMENT_EXCLUSION_EMBED},
               income_expense_items!inner ( id, amount, income_expense_types!inner ( is_deposit ) )`,
            )
            .is('contract_id', null)
            .is('deleted_at', null)
            .is('management_exclusion', null)
            .eq('type', 'INCOME')
            .in('approval_status', ['APPROVED', 'UNAPPROVED', 'CANCELLED'])
            .eq('income_expense_items.income_expense_types.is_deposit', true)
            .order('voucher_date', { ascending: false })
            .order('id', { ascending: true });
          if (buildingIds && buildingIds.length > 0) {
            query = query.in('building_id', buildingIds);
          }
          return query.range(from, to);
        },
        { label: 'deposits.reservation' },
      );
      if (data === null) throw new Error('Lỗi tải cọc giữ chỗ');

      const neededSettlementSources = new Set((data ?? [])
        .filter((voucher: { id: string; settled?: unknown }) => voucher.settled)
        .map((voucher: { id: string }) => voucher.id));
      const settlementBySource = new Map<string, NonNullable<ReservationDepositRow['settlement']>>();
      let settlementCursor = null;
      while (neededSettlementSources.size > settlementBySource.size) {
        const result = reservationSettlementListSchema.parse(await invokeReservationSettlementRpc(settlementRpc, 'get_reservation_settlements_v1', reservationSettlementListArgs({ buildingIds, cursor: settlementCursor }), reservationSettlementListSchema));
        for (const row of result.rows) {
          if (neededSettlementSources.has(row.sourceVoucherId)) {
            const settlement = reservationSettlementSchema.parse(row);
            settlementBySource.set(row.sourceVoucherId, {
              id: settlement.id!, depositAmount: settlement.depositAmount!, retainedAmount: settlement.retainedAmount!,
              refundAmount: settlement.refundAmount!, refundedAmount: settlement.refundedAmount!, refundRemaining: settlement.refundRemaining!,
              refundState: settlement.refundState!, roomReleased: settlement.roomReleased!,
            });
          }
        }
        if (!result.nextCursor) break;
        settlementCursor = result.nextCursor;
      }
      // !inner có thể nhân dòng nếu phiếu có >1 item cọc → dedupe theo id.
      const seen = new Set<string>();
      const rows: ReservationDepositRow[] = [];
      for (const v of (data ?? []) as any[]) {
        if (seen.has(v.id)) continue;
        seen.add(v.id);
        if(!['UNAPPROVED','APPROVED','CANCELLED'].includes(v.approval_status)) throw new TypeError('Chưa đọc được trạng thái phiếu cọc.');
        // Số CỌC = Σ item cọc (embed đã lọc is_deposit) — không đếm thừa phần
        // không-cọc nếu phiếu trộn nhập tay.
        const depositSum = financialReadRows(v.income_expense_items).reduce<number>(
          (s: number, it: any) => s + financialReadNumber(it.amount),
          0,
        );
        rows.push({
          id: v.id,
          code: v.code ?? null,
          name: v.name,
          payer_name: v.payer_name ?? null,
          total_amount: depositSum,
          voucher_date: v.voucher_date,
          approval_status: v.approval_status,
          approval_version: Number(v.approval_version ?? 1),
          building_id: v.building?.id ?? v.building_id ?? '',
          building_name: v.building?.name ?? '—',
          room_id: v.room?.id ?? v.room_id ?? null,
          room_name: v.room?.name ?? null,
          settlement_status: v.settled ? 'SETTLED' : 'UNSETTLED',
          settlement: settlementBySource.get(v.id) ?? null,
        });
      }
      return rows;
    },
  })

