useQuery({
    meta:{feedback:"inline"},
    queryKey: ['room-cash-lifecycle', roomId],
    enabled: !!roomId,
    queryFn: async (): Promise<LifecyclePayload> => {
      const { data, error } = await supabase.rpc('get_room_cash_lifecycle_v1', {
        p_room_id: roomId!,
      });
      if (error) throw error;
      const value=data as unknown as Partial<LifecyclePayload>|null;
      if(!value?.room || value.room.id!==roomId || !Array.isArray(value.contracts) || !Array.isArray(value.segments) || !Array.isArray(value.events) || !Array.isArray(value.vacancies)) throw new TypeError("Unconfirmed room lifecycle source");
      return value as LifecyclePayload;
    },
  })

useQuery({
    queryKey: ['profit-report', 'room-contract-extras', ids],
    enabled: ids.length > 0,
    staleTime: 60_000,
    queryFn: async (): Promise<RoomContractExtras & { partial: boolean }> => {
      const [transfers, extensions, links] = await Promise.all([
        fetchAllRows<TransferRow>(
          (f, t) => supabase
            .from('contract_transfers')
            .select('id, contract_id, transfer_type, transfer_date, old_room_id, new_room_id')
            .in('contract_id', ids)
            .in('status', ['APPROVED', 'COMPLETED'])
            .order('id', { ascending: true })
            .range(f, t),
          { label: 'room-contract-extras.transfers' },
        ),
        fetchAllRows<ExtensionRow>(
          (f, t) => supabase
            .from('contract_extensions')
            .select('id, contract_id, extension_date, old_end_date, new_end_date, status')
            .in('contract_id', ids)
            .order('id', { ascending: true })
            .range(f, t),
          { label: 'room-contract-extras.extensions' },
        ),
        fetchAllRows<CustomerLinkRow>(
          (f, t) => supabase
            .from('contract_customers')
            .select('id, contract_id, is_representative, customers ( full_name, phone )')
            .in('contract_id', ids)
            .order('id', { ascending: true })
            .range(f, t),
          { label: 'room-contract-extras.customers' },
        ),
      ]);

      // Tên phòng đích của chuyển phòng — chỉ để ghi "Chuyển sang phòng 402".
      const roomIds = [...new Set((transfers ?? []).map((x) => x.new_room_id).filter((x): x is string => !!x))];
      const rooms = roomIds.length
        ? await fetchAllRows<{ id: string; name: string | null }>(
            (f, t) => supabase.from('rooms').select('id, name').in('id', roomIds).order('id', { ascending: true }).range(f, t),
            { label: 'room-contract-extras.rooms' },
          )
        : [];
      const roomName = new Map((rooms ?? []).map((r) => [r.id, r.name]));

      const customers = new Map<string, { name: string | null; phone: string | null }>();
      // Đại diện thắng; không có đại diện thì lấy khách đầu tiên có tên.
      for (const l of [...(links ?? [])].sort((a, b) => Number(b.is_representative) - Number(a.is_representative))) {
        if (customers.has(l.contract_id) || !l.customers?.full_name) continue;
        customers.set(l.contract_id, { name: l.customers.full_name, phone: l.customers.phone });
      }

      return {
        transfers: (transfers ?? []).map((x) => ({
          contractId: x.contract_id,
          type: x.transfer_type,
          date: x.transfer_date,
          oldRoomId: x.old_room_id,
          newRoomId: x.new_room_id,
          newRoomName: x.new_room_id ? roomName.get(x.new_room_id) ?? null : null,
        })),
        extensions: (extensions ?? [])
          .filter((x) => !EXTENSION_BO.has((x.status ?? '').toUpperCase()))
          .map((x) => ({
            contractId: x.contract_id,
            date: x.extension_date,
            oldEndDate: x.old_end_date,
            newEndDate: x.new_end_date,
          })),
        customers,
        partial: transfers === null || extensions === null || links === null || rooms === null,
      };
    },
  })

useQuery({
    queryKey: ["room-ids-by-code", code.toLowerCase(), buildingKey],
    enabled,
    staleTime: 5 * 60 * 1000,
    queryFn: async (): Promise<string[]> => {
      // ilike KHÔNG có ký tự đại diện = so khớp chính xác (case-insensitive).
      let q = (supabase
        .from("rooms" as any)
        .select("id") as any)
        .is("deleted_at", null)
        .ilike("name", code);
      if (buildingIds && buildingIds.length) {
        q = q.in("building_id", buildingIds);
      }
      const { data, error } = await q;
      if (error) {
        console.error("useRoomIdsByCode error:", error);
        throw error;
      }
      return ((data ?? []) as any[]).map((r) => r.id as string);
    },
  })

useQuery({
    enabled: (options?.enabled ?? true) && !!roomId,
    queryKey: ["room-price-history", roomId, limit],
    meta: { errorDisplay: "inline", label: "lịch sử giá" },
    queryFn: async (): Promise<RoomPriceHistoryEntry[]> => {
      const { data, error } = await supabase
        .from("room_price_history")
        .select("*, contract:contracts(contract_number)")
        .eq("room_id", roomId!)
        .order("changed_at", { ascending: false })
        .limit(limit);

      if (error) {
        console.error("useRoomPriceHistory error:", error);
        throw error;
      }

      const rows = (data ?? []) as Array<
        RoomPriceHistoryRow & { contract?: { contract_number: string | null } | null }
      >;

      // Tên người thao tác nằm ở profiles — join riêng vì room_price_history
      // không có FK sang profiles (changed_by chỉ là auth uid).
      const actorIds = [...new Set(rows.map((r) => r.changed_by).filter(Boolean))];
      const names = new Map<string, string>();
      if (actorIds.length > 0) {
        const { data: profiles } = await supabase
          .from("profiles")
          .select("id, full_name")
          .in("id", actorIds as string[]);
        for (const p of profiles ?? []) {
          if (p.full_name) names.set(p.id, p.full_name);
        }
      }

      return rows.map(({ contract, ...row }) => ({
        ...row,
        contract_number: contract?.contract_number ?? null,
        changed_by_name: row.changed_by ? names.get(row.changed_by) ?? null : null,
      }));
    },
  })

useQuery({
    enabled: options?.enabled ?? true,
    queryKey: buildingId ? ["rooms", "building", buildingId] : ["rooms"],
    queryFn: async () => {
      // PHÂN TRANG: key ["rooms"] được gọi org-wide (5 dialog dùng chung). Một
      // request trần chỉ lấy được 1000 dòng và PostgREST KHÔNG báo gì —
      // portfolio >1000 phòng thì dropdown thiếu phòng mà không ai biết.
      // `id` là tiebreaker duy nhất, bắt buộc để ranh giới trang không sót/trùng
      // (giao kèo ở đầu src/lib/supabaseFetchAll.ts).
      const rows = await fetchAllRows((from, to) => {
        let query = supabase
          .from("rooms")
          .select(`
            *,
            building:buildings(id, name, code)
          `)
          .is("deleted_at", null)
          .order("building_id", { ascending: true })
          .order("floor", { ascending: true })
          .order("name", { ascending: true })
          .order("id", { ascending: true });

        if (buildingId) {
          query = query.eq("building_id", buildingId);
        }

        return query.range(from, to);
      }, { label: buildingId ? "rooms-building" : "rooms" });

      if (rows === null) {
        // KHÔNG nuốt lỗi: throw để vào isError + retry (trước trả [] làm dropdown rỗng âm thầm).
        // fetchAllRows đã console.error chi tiết lỗi PostgREST.
        throw new Error("Không tải được danh sách căn hộ. Hãy thử lại.");
      }

      // Sắp xếp theo toà nhà rồi tên phòng (MB* → G* → L* → 1,2,3,4...) — áp dụng
      // cho mọi nơi dùng useRooms: dropdown chọn phòng, sơ đồ toà nhà, danh sách...
      const rooms = rows as unknown as RoomWithRelations[];
      return [...rooms].sort((a, b) =>
        compareBuildingThenRoom(
          a.building?.name ?? "",
          a.name ?? "",
          b.building?.name ?? "",
          b.name ?? "",
        ),
      );
    },
  })

