useQuery({
    queryKey: ["rooms-with-contracts", buildingId || "all"],
    queryFn: async (): Promise<RoomWithContract[]> => {
      // PHÂN TRANG: RoomsPage gọi hook này KHÔNG kèm buildingId (org-wide), và
      // join 4 tầng làm mỗi dòng nặng. Không `.range()` thì PostgREST cắt ở 1000
      // phòng và sơ đồ toà nhà mất phòng mà không báo gì. `id` là tiebreaker duy
      // nhất; order phải ổn định thì ranh giới trang mới không sót/trùng.
      const rows = await fetchAllRows<SupabaseRoomRow>((from, to) => {
        let query = supabase
          .from("rooms")
          .select(
            `id, name, rent_price, floor, status, building_id,
             contracts!inner (
               id, end_date, rent_price, status,
               contract_customers!contract_customers_contract_id_fkey (
                 is_representative,
                 customer:customers!contract_customers_customer_id_fkey ( id, full_name )
               )
             )`
          )
          .is("deleted_at", null)
          .in("contracts.status", ["ACTIVE"])
          .order("id", { ascending: true }) as any;

        if (buildingId) {
          query = query.eq("building_id", buildingId);
        }

        return query.range(from, to);
      }, { label: "rooms-with-contracts" });

      if (rows === null) {
        // fetchAllRows fail-closed: null = LỖI, không phải "không có phòng nào".
        throw new Error("Không tải được danh sách phòng kèm hợp đồng. Hãy thử lại.");
      }

      return rows.map((room) => {
        const c: SupabaseContractRow | undefined = room.contracts?.[0];
        const reps = c?.contract_customers || [];
        const repTenant =
          reps.find((cc) => cc.is_representative)?.customer || reps[0]?.customer;
        return {
          id: room.id,
          name: room.name,
          rent_price: room.rent_price,
          floor: room.floor,
          status: room.status,
          activeContract: c
            ? {
                id: c.id,
                end_date: c.end_date,
                rent_price: c.rent_price,
                tenant: repTenant ? { full_name: repTenant.full_name } : undefined,
              }
            : undefined,
        };
      });
    },
  })

useQuery<ManagerConfigRow[]>({
    queryKey: ["salary-config-list"],
    meta: {label:"cấu hình lương",errorDisplay:"inline"},
    queryFn: async () => {
      const { data: cfg , error: sourceError1 } = await (supabase
        .from("manager_salary_config")
        .select("*") as any)
        .order("created_at", { ascending: true });
      if (sourceError1) throw sourceError1;
      const rows = (cfg || []) as any[];
      const ids = rows.map((r) => r.staff_id);
      const nameById = new Map<string, string>();
      if (ids.length) {
        const { data: profs , error: sourceError2 } = await (supabase.from("profiles").select("id, full_name") as any).in("id", ids);
        if (sourceError2) throw sourceError2;
        for (const p of (profs || []) as any[]) nameById.set(p.id, p.full_name);
      }
      const roomIds = rows.map((r) => r.room_id).filter(Boolean);
      const roomNameById = new Map<string, string>();
      if (roomIds.length) {
        const { data: rms , error: sourceError3 } = await (supabase.from("rooms").select("id, name") as any).in("id", roomIds);
        if (sourceError3) throw sourceError3;
        for (const rm of (rms || []) as any[]) roomNameById.set(rm.id, rm.name);
      }
      return rows.map((r) => ({
        id: r.id,
        staff_id: r.staff_id,
        full_name: nameById.get(r.staff_id) || r.alias || "Quản lý",
        base_salary: Number(r.base_salary) || 0,
        default_room_rent: Number(r.default_room_rent) || 0,
        income_goal: Number(r.income_goal) || 0,
        role_title: r.role_title || "Quản lý vận hành",
        alias: r.alias,
        room_id: r.room_id ?? null,
        room_name: r.room_id ? (roomNameById.get(r.room_id) ?? null) : null,
        is_active: !!r.is_active,
      }));
    },
  })

useMutation({
    mutationFn: async (input: SaveManagerConfigInput) => {
      const user = await getSessionUser();
      if (!user) throw new Error("Chưa đăng nhập");
      if (input.id) {
        const { data, error } = await supabase
          .from("manager_salary_config")
          .update({
            base_salary: input.base_salary,
            default_room_rent: input.default_room_rent,
            income_goal: input.income_goal ?? 0,
            role_title: input.role_title,
            alias: input.alias ?? null,
            room_id: input.room_id ?? null,
          })
          .eq("id", input.id).select("id").single();
        if (error) throw error;
        if (!data?.id) throw new TypeError("Unconfirmed salary config result");
      } else {
        if (!input.staff_id) throw new Error("Chưa chọn nhân viên");
        const { data, error } = await supabase.from("manager_salary_config").insert({
          user_id: user.id,
          staff_id: input.staff_id,
          base_salary: input.base_salary,
          default_room_rent: input.default_room_rent,
          income_goal: input.income_goal ?? 0,
          role_title: input.role_title,
          alias: input.alias ?? null,
          room_id: input.room_id ?? null,
        }).select("id").single();
        if (error) throw error;
        if (!data?.id) throw new TypeError("Unconfirmed salary config result");
      }
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["salary-config-list"] });
      qc.invalidateQueries({ queryKey: ["manager-salary"] });
      toast.success("Đã lưu cấu hình quản lý");
