useQuery({
    queryKey: ["refund-log", accountId, start, end],
    enabled: !!accountId,
    meta: { feedback: "inline" },
    queryFn: async (): Promise<{
      rows: RefundRow[];
      total: number;
      count: number;
      accountName: string | null;
      mode: LedgerMode;
    }> => {
      if (!accountId)
        return { rows: [], total: 0, count: 0, accountName: null, mode: "refund" };

      const { data: acc, error: accountError } = await supabase
        .from("accounts")
        .select("id, name")
        .eq("id", accountId)
        .maybeSingle();
      if (accountError) throw accountError;
      if (!acc || acc.id !== accountId || typeof acc.name !== "string") {
        throw new Error("Chưa xác nhận được thông tin sổ quỹ để tải lịch sử tiền thối.");
      }
      const mode = detectMode(acc.name);
      const filterColumn =
        mode === "rounding" ? "rounding_account_id" : "change_account_id";
      const amountColumn = mode === "rounding" ? "rounding_amount" : "change_amount";

      const { data, error } = await supabase
        .from("income_expenses" as any)
        .select(
          `id, voucher_date, code, invoice_id, payer_name, change_amount, rounding_amount, total_amount, notes,
           building:buildings!income_expenses_building_id_fkey ( name ),
           room:rooms!income_expenses_room_id_fkey ( name ),
           invoice:invoices!income_expenses_invoice_id_fkey ( invoice_number )`
        )
        .eq(filterColumn, accountId)
        .eq("approval_status", "APPROVED")
        .is("deleted_at", null)
        .gte("voucher_date", start)
        .lte("voucher_date", end)
        .order("voucher_date", { ascending: false });

      if (error) {
        console.error("useRefundLog error:", error);
        throw error;
      }

      const rows: RefundRow[] = (financialReadRows(data) as Array<Record<string, any>>).map((v) => ({
        id: v.id,
        voucher_date: v.voucher_date,
        code: v.code,
        invoice_id: v.invoice_id,
        invoice_number: v.invoice?.invoice_number ?? null,
        building_name: v.building?.name ?? null,
        room_name: v.room?.name ?? null,
        payer_name: v.payer_name,
        change_amount: financialReadNumber(v[amountColumn]),
        total_amount: financialReadNumber(v.total_amount),
        notes: v.notes,
      }));
      const total = rows.reduce((s, r) => s + r.change_amount, 0);
      return { rows, total, count: rows.length, accountName: acc?.name ?? null, mode };
    },
  })

useQuery({
    queryKey: ["phong-trong", token],
    enabled: !!token,
    staleTime: 5_000,
    refetchOnWindowFocus: 'always',
    refetchOnReconnect: 'always',
    refetchIntervalInBackground: false,
    retry: false,
    refetchInterval: (query) => query.state.error instanceof PublicRoomLinkError ? false : roomSalePollingInterval(query.state.error ? query.state.errorUpdateCount : 0),
    queryFn: async () => {
      if (!token) throw new PublicRoomLinkError();
      const { data, error } = await supabase.rpc("get_public_available_rooms", { p_token: token });
      if (error) throw error;
      // RPC trả NULL khi token không tồn tại/đã thu hồi; payload rỗng hợp lệ
      // vẫn có buildings/rooms. Không biến hai kết quả này thành cùng một []
      // rồi để UI thế bằng danh sách mẫu.
      if (data === null) throw new PublicRoomLinkError();
      return mapPayloadToBuildings(parseRoomSalePayload(data));
    },
  })

